<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{savePlayer}from'../stores';import{useI18n}from'../i18n';const name=ref(''),error=ref(false),router=useRouter(),{t,locale,setLocale}=useI18n();function go(){if(savePlayer(name.value))router.push('/home');else error.value=true}</script>
<template><section class="screen welcome"><div class="lang"><button v-for="l in ['it','en','es']" :key="l" :class="{active:locale===l}" @click="setLocale(l as any)">{{l.toUpperCase()}}</button></div><div class="globe">🌍</div><h1>FLAG<br><em>STREAK</em></h1><p>{{t('choose')}}</p><form @submit.prevent="go"><input v-model="name" maxlength="18" autocomplete="nickname" placeholder="Nome" aria-label="Nickname" :aria-invalid="error"><button class="primary">{{t('continue')}} <span>→</span></button></form></section></template>
